\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Professional Color Theme ──
\definecolor{primary}{HTML}{0F172A}      % deep navy
\definecolor{secondary}{HTML}{1E40AF}     % royal blue
\definecolor{accent}{HTML}{F59E0B}        % amber/gold
\definecolor{bgposter}{HTML}{0F172A}       % deep navy background
\definecolor{carddark}{HTML}{1E293B}      % card background
\definecolor{redbg}{HTML}{1E293B}         % tinted card
\definecolor{bluebg}{HTML}{172554}        % blue tint
\definecolor{goldbg}{HTML}{451A03}        % gold tint
\definecolor{textlight}{HTML}{F8FAFC}     % light text
\definecolor{textgray}{HTML}{94A3B8}       % muted text
\definecolor{stathighlight}{HTML}{1E3A5F} % stat highlight
\definecolor{barcolor}{HTML}{2563EB}      % bar chart color

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=carddark,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=carddark,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goldbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{barcolor},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{barcolor},
    coltitle=barcolor, colbacktitle=bluebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={barcolor!50},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stathighlight,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=stathighlight,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries The World's Most Valuable Companies in 2025}\\[10pt]
  {\fontsize{28}{34}\selectfont\color{textgray} A Comparative Snapshot of Global Market Leadership}\\[6pt]
  {\fontsize{22}{26}\selectfont\color{accent} Data as of Mid-2025}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!15, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{accent} \$4.82T}\\[4pt]
      {\fontsize{22}{26}\selectfont\color{textlight} NVIDIA — #1 Globally}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{secondary} 11}\\[4pt]
      {\fontsize{22}{26}\selectfont\color{textlight} Trillion-Dollar Companies}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{accent} \$142.9T}\\[4pt]
      {\fontsize{22}{26}\selectfont\color{textlight} Total Global Market Cap}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══ ROW A: TRILLION-DOLLAR CLUB (Left) + COUNTRY DOMINANCE (Middle) + SECTOR (Right) ══
\posterbox[goldcard, title={The Trillion-Dollar Club}
]{name=trillion, column=1, between=row6 and row13}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \color{accent}\textbf{NVIDIA} \$4.82T — AI dominance
    \item \textbf{Alphabet} \$4.03T — Search \& Cloud
    \item \textbf{Apple} \$3.87T — Devices \& Services
    \item \textbf{Microsoft} \$3.12T — Cloud \& AI
    \item \textbf{Amazon} \$2.69T — E-commerce \& Cloud
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{textlight}
    Top 5 combined: \textbf{\$18.5T} $\approx$ 13\% of all tracked value
  }}
}

\posterbox[darkcard, title={Country Dominance}
]{name=country, column=2, between=row6 and row13}{
  \fontsize{32}{40}\selectfont
  \colorbox{secondary!25}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}
    {\fontsize{48}{56}\selectfont\bfseries\color{secondary} 15}\\[2pt]
    {\fontsize{24}{28}\selectfont\color{textlight} of 20 are U.S. Companies}\\[4pt]
    \vspace{2pt}
  }}
  \vspace{6pt}
  \begin{itemize}[itemsep=8pt]
    \item \color{accent}\textbf{Taiwan}: TSMC (\$1.88T)
    \item \textbf{Saudi Arabia}: Saudi Aramco
    \item \textbf{South Korea}: Samsung
    \item \textbf{China}: Tencent
    \item \textbf{Netherlands}: ASML
  \end{itemize}
}

\posterbox[bluecard, title={Sector Concentration}
]{name=sector, column=3, between=row6 and row13}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \color{barcolor}\textbf{Tech \& Semiconductors} dominate top tier
    \item \textbf{Software/Internet} platforms fill top ranks
    \item \textbf{Finance}: Berkshire Hathaway
    \item \textbf{Energy}: Saudi Aramco
    \item \textbf{Automotive}: Tesla
  \end{itemize}
  \vspace{6pt}
  \colorbox{barcolor!20}{\parbox{0.92\linewidth}{%
    \fontsize{24}{30}\selectfont\color{textlight}
    7 of 11 trillion-dollar firms are tech/semiconductor
  }}
}

% ══ ROW B: TOP 20 TABLE (Left) + PERSPECTIVE (Middle+Right) ══
\posterbox[darkcard, title={The Top 20 — Full Rankings}
]{name=top20, column=1, between=row13 and row18}{
  \fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.4}
  \begin{tabular}{rllr}
    \rowcolor{secondary!20}
    \color{textlight}\textbf{Rank} & \color{textlight}\textbf{Company} & \color{textlight}\textbf{Country} & \color{textlight}\textbf{Cap}\\
    \rowcolor{primary!10}
    1 & NVIDIA & USA & \$4.82T\\
    \rowcolor{secondary!20}
    2 & Alphabet & USA & \$4.03T\\
    \rowcolor{primary!10}
    3 & Apple & USA & \$3.87T\\
    \rowcolor{secondary!20}
    4 & Microsoft & USA & \$3.12T\\
    \rowcolor{primary!10}
    5 & Amazon & USA & \$2.69T\\
    \rowcolor{secondary!20}
    6 & Broadcom & USA & \$1.89T\\
    \rowcolor{primary!10}
    7 & TSMC & Taiwan & \$1.88T\\
    \rowcolor{secondary!20}
    8 & Saudi Aramco & Saudi Arabia & \$1.77T\\
    \rowcolor{primary!10}
    9 & Meta & USA & \$1.71T\\
    \rowcolor{secondary!20}
    10 & Tesla & USA & \$1.46T\\
    \rowcolor{primary!10}
    11 & Berkshire H. & USA & \$1.02T\\
    \rowcolor{secondary!20}
    12--20 & \textit{Samsung, Tencent, ASML, Meta, etc.} & \textit{Various} & \textit{\$0.55--0.97T}
  \end{tabular}
}

\posterbox[highlightcard, title={Putting It in Perspective}
]{name=perspective, column=2, span=2, between=row13 and row18}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item \color{accent}\textbf{NVIDIA alone} exceeds value of bottom 5,000+ companies
    \item \textbf{Top 10} ($\sim$0.09\% of firms) hold \textbf{\~18\%} of total global value
    \item \textbf{9x drop} from rank 1 (\$4.82T) to rank 20 (\$554B)
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.96\linewidth}{%
    \centering
    {\fontsize{26}{32}\selectfont\color{textlight}
    Top 10 Combined: \textbf{\$25.4T}}\\[4pt]
    {\fontsize{22}{26}\selectfont\color{textgray}
    Out of \$142.9T across 10,796 tracked companies}
  }}
}

% ══ BOTTOM: KEY INSIGHT ══
\posterbox[
  enhanced, colback=accent!15, colframe=accent, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=takeaway, column=1, span=3, between=row18 and bottom}{
  {\fontsize{28}{34}\selectfont\color{accent}\textbf{Key Insight:}} {\fontsize{26}{32}\selectfont\color{textlight}
  A handful of U.S. tech giants command a staggering share of global market value — with NVIDIA, Alphabet, and Apple together worth more than most national economies.}
}

\end{tcbposter}
\end{document}

